@icontract.ensure(lambda nums, target, result: all(
    nums[result[0]] + nums[j] != target for j in range(result[0] + 1, result[1])))
def twoSum(nums: List[int], target: int) -> Tuple[int, int]:
    n = len(nums)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                return (i, j)
    raise ValueError("no pair sums to target")
